head.script:
// 테스트 설명, 유효성 값 설정
// 담당 범위(3개 분할 중 _3) : 선택 안내, 전체 선택 아이템 / GridViewItemSet 리스트창
//  - _1 : displayMode 값별 입력창, 리스트창 표시 형식 / 구분자 / 바인딩된 DataCollection 저장값
//  - _2 : 편집 상태의 입력창 (searchTarget, displayModeSync)
scwin.tData = {
    "description" : "[autoComplete > P > displayMode]<br/>AutoComplete 컴포넌트의 입력창과 아이템 리스트창에 아이템이 표시되는 형식을 설정합니다.",
    "validation" : [
        "allOption, chooseOption 속성으로 추가된 아이템에는 적용되지 않습니다.",
        "아이템이 GridViewItemSet 으로 정의된 경우 아이템 리스트창에는 적용되지 않습니다.",
    ]
}

// 아이템
scwin.arrCity = [
    { "label" : "서울", "value" : "SEL" },
    { "label" : "부산", "value" : "BSN" },
    { "label" : "대구", "value" : "DGU" },
    { "label" : "인천", "value" : "ICN" }
];

// 표시값 확인 버튼을 누르는 시점의 리스트창 아이템
scwin.gVar = { "arrItem" : [] };



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    // 아이템 DataList 생성 (BindItemSet / GridViewItemSet 용)
    let strDlt = '';
    strDlt += '<w2:dataList ' + $c.gcm.getNameSpace() + ' baseNode="list" repeatNode="map" id="dlt_city">';
    strDlt += '<w2:columnInfo>';
    strDlt += '<w2:column id="label" name="label" dataType="text"></w2:column>';
    strDlt += '<w2:column id="value" name="value" dataType="text"></w2:column>';
    strDlt += '</w2:columnInfo>';
    strDlt += '</w2:dataList>';
    $p.data.create(strDlt);
    dlt_city.setJSON(scwin.arrCity);

    // 정적 select1 은 초기 selectedIndex 가 적용되지 않으므로 기본값 명시 설정 (displayMode=value delim label, chooseOption=true, allOption=true, 아이템 정의=ItemSet)
    con_displayMode.setValue("value delim label");
    con_chooseOption.setValue("2");
    con_allOption.setValue("2");
    con_itemset.setValue("itemset");

    // 표시값 확인 버튼 클릭 시 목록이 먼저 닫히므로 mousedown capture 단계에서 리스트창 아이템을 기록
    btn_getDisplayInfo.render.addEventListener("mousedown", scwin.captureListState, true);

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    $c.gcm.createLabel('label="[전제]\n- 아이템(Label / Value) : 서울 / SEL, 부산 / BSN, 대구 / DGU, 인천 / ICN\n- delimiter 는 : 로 고정\n- GridViewItemSet 의 리스트창은 Label Column, Value Column 순서로 구성 (결과창에는 Column 값을 | 로 구분)\n[절차]\n1. 화살표 버튼으로 목록을 연 상태에서 표시값 확인\n2. 목록에서 아이템 선택 -> 표시값 확인"', '', 'label1');

    // 미설정 옵션은 createCList 가 속성에서 제외 (gdl_boolean 은 getText 로 읽는다)
    let properties = {
        displayMode : con_displayMode.getValue(),
        delimiter : ":",
        chooseOption : con_chooseOption.getText(),
        allOption : con_allOption.getText(),
    }

    let cList = $c.gcm.createCList(properties);

    let strTarget = '';
    strTarget += '<w2:autoComplete ' + $c.gcm.getNameSpace() + ' ' + cList + ' style="width:200px; height:30px;">';
    strTarget += '<w2:choices>';
    if (con_itemset.getValue() === "gridViewItemset") {
        // GridViewItemSet
        strTarget += '<w2:gridViewItemset nodeset="data:dlt_city" label="label" value="value">';
        strTarget += '<w2:item ref="label" header="label"></w2:item>';
        strTarget += '<w2:item ref="value" header="value"></w2:item>';
        strTarget += '</w2:gridViewItemset>';
    } else if (con_itemset.getValue() === "bindItemset") {
        // BindItemSet (DataList 바인딩)
        strTarget += '<w2:itemset nodeset="data:dlt_city">';
        strTarget += '<w2:label ref="label"></w2:label>';
        strTarget += '<w2:value ref="value"></w2:value>';
        strTarget += '</w2:itemset>';
    } else {
        // ItemSet (아이템 직접 정의)
        for (let i = 0; i < scwin.arrCity.length; i++) {
            strTarget += '<w2:item>';
            strTarget += '<w2:label>' + scwin.arrCity[i].label + '</w2:label>';
            strTarget += '<w2:value>' + scwin.arrCity[i].value + '</w2:value>';
            strTarget += '</w2:item>';
        }
    }
    strTarget += '</w2:choices>';
    strTarget += '</w2:autoComplete>';

    await $p.dynamicCreate("target1", "autoComplete", strTarget, $c.gcm.getTestGroup());
}



// 리스트창 요소가 화면에 표시된 상태인지 반환
scwin.isVisible = function (elem) {
    if (!elem) {
        return false;
    }
    let objStyle = getComputedStyle(elem);
    return objStyle.display !== "none" && objStyle.visibility !== "hidden";
}



// 버튼 mousedown 시점(목록이 닫히기 전)의 리스트창 표시 아이템 기록
scwin.captureListState = function (e) {
    scwin.gVar.arrItem = [];

    let itemTableElem = document.querySelector("[id='" + target1.id + "_itemTable']");
    let gridTableElem = document.querySelector("[id='" + target1.id + "_gridViewItemTable']");

    if (scwin.isVisible(gridTableElem)) {
        // GridViewItemSet : Row 별 Column 값을 | 로 구분
        let rowList = gridTableElem.querySelectorAll("[id='" + target1.id + "_gridViewItemTable_gridView_body_tbody'] tr.grid_body_row");
        for (let i = 0; i < rowList.length; i++) {
            if (rowList[i].offsetHeight > 0) {
                let arrCell = Array.prototype.map.call(rowList[i].querySelectorAll("td"), function (cell) {
                    return cell.textContent;
                });
                scwin.gVar.arrItem.push(arrCell.join(" | "));
            }
        }
    } else if (scwin.isVisible(itemTableElem)) {
        // ItemSet / BindItemSet : 숨겨진 Row 는 제외하고 화면에 보이는 아이템만 수집
        let rowList = itemTableElem.querySelectorAll("[id='" + target1.id + "_itemTable_main'] tr");
        for (let i = 0; i < rowList.length; i++) {
            if (rowList[i].offsetHeight > 0) {
                scwin.gVar.arrItem.push(rowList[i].textContent);
            }
        }
    }
};



// 리스트창 아이템과 선택된 아이템의 입력창 표시 텍스트 출력 (validation 1, 2)
scwin.btn_getDisplayInfo_onclick = function (e) {
    let bottom = wf_body_bottom.getObj("scwin");

    if (scwin.gVar.arrItem.length > 0) {
        bottom.setReturnValue("리스트창 아이템 : " + scwin.gVar.arrItem.join(" / "));
    }

    let labelElem = document.querySelector("[id='" + target1.id + "_label']");
    if (labelElem.textContent !== "") {
        bottom.setReturnValue("입력창 표시 텍스트 : " + labelElem.textContent);
    }
};
